//! Tests for src/game.rs (17 tests). Do not edit this file.
//!
//! Run just these with: cargo test game::

use super::*;

/// The board most tests use. The playable area is x and y from 1 to 28.
fn new_game() -> Game {
    Game::new(30, 30)
}

// ---------- Phase 6: creating and restarting ----------

#[test]
fn new_game_starting_state() {
    let game = Game::new(20, 15);
    assert_eq!(game.width, 20);
    assert_eq!(game.height, 15);
    assert_eq!(game.snake.head_position(), (4, 2));
    assert_eq!(game.snake.head_direction(), Direction::Right);
    assert!(game.food_exists);
    assert_eq!((game.food_x, game.food_y), (6, 4));
    assert!(!game.game_over);
    assert_eq!(game.waiting_time, 0.0);
}

#[test]
fn restart_resets_everything_but_board_size() {
    let mut game = Game::new(20, 15);
    game.snake.move_forward(Some(Direction::Down));
    game.food_exists = false;
    game.food_x = 1;
    game.food_y = 1;
    game.game_over = true;
    game.waiting_time = 3.0;

    game.restart();

    assert_eq!((game.width, game.height), (20, 15));
    assert_eq!(game.snake.head_position(), (4, 2));
    assert_eq!(game.snake.head_direction(), Direction::Right);
    assert!(game.food_exists);
    assert_eq!((game.food_x, game.food_y), (6, 4));
    assert!(!game.game_over);
    assert_eq!(game.waiting_time, 0.0);
}

// ---------- Phase 7: collisions, eating, food ----------

#[test]
fn alive_when_moving_into_open_space() {
    let game = new_game();
    assert!(game.check_if_snake_alive(None));
    assert!(game.check_if_snake_alive(Some(Direction::Up)));
    assert!(game.check_if_snake_alive(Some(Direction::Down)));
}

#[test]
fn dies_when_hitting_any_wall() {
    let mut game = new_game();

    // Right wall: head at (28, 2), next cell (29, 2) is the wall.
    game.snake = Snake::new(26, 2);
    assert!(!game.check_if_snake_alive(None));

    // Top wall: head at (4, 1), moving up reaches row 0.
    game.snake = Snake::new(2, 1);
    assert!(!game.check_if_snake_alive(Some(Direction::Up)));

    // Bottom wall: head at (4, 28), moving down reaches row 29.
    game.snake = Snake::new(2, 28);
    assert!(!game.check_if_snake_alive(Some(Direction::Down)));

    // Left wall: steer the snake until its head is at (1, 4).
    game.snake = Snake::new(1, 5);
    game.snake.move_forward(Some(Direction::Up));
    game.snake.move_forward(Some(Direction::Left));
    game.snake.move_forward(Some(Direction::Left));
    assert_eq!(game.snake.head_position(), (1, 4));
    assert!(!game.check_if_snake_alive(Some(Direction::Left)));
}

#[test]
fn dies_when_hitting_itself() {
    let mut game = new_game();
    // Grow the snake to 5 blocks, then curl it round so the head is
    // directly below its own body.
    game.snake.move_forward(None);
    game.snake.restore_tail();
    game.snake.move_forward(None);
    game.snake.restore_tail();
    game.snake.move_forward(Some(Direction::Down));
    game.snake.move_forward(Some(Direction::Left));
    assert_eq!(game.snake.head_position(), (5, 3));

    assert!(!game.check_if_snake_alive(Some(Direction::Up)));
}

#[test]
fn check_eating_grows_snake_and_removes_food() {
    let mut game = new_game();
    game.snake.move_forward(None); // head is now at (5, 2)
    game.food_x = 5;
    game.food_y = 2;

    game.check_eating();

    assert!(!game.food_exists);
    assert_eq!(game.snake.len(), 4);
}

#[test]
fn check_eating_does_nothing_when_not_on_food() {
    let mut game = new_game();
    game.snake.move_forward(None); // head at (5, 2), food still at (6, 4)

    game.check_eating();

    assert!(game.food_exists);
    assert_eq!(game.snake.len(), 3);
}

#[test]
fn add_food_stays_inside_walls_and_off_the_snake() {
    // A tiny board makes it easy to catch food landing on a wall.
    let mut game = Game::new(8, 6);
    let mut seen = std::collections::HashSet::new();

    for _ in 0..500 {
        game.food_exists = false;
        game.add_food();

        assert!(game.food_exists);
        assert!(
            game.food_x >= 1 && game.food_x <= 6,
            "food_x = {}",
            game.food_x
        );
        assert!(
            game.food_y >= 1 && game.food_y <= 4,
            "food_y = {}",
            game.food_y
        );
        assert!(!game.snake.overlap_tail(game.food_x, game.food_y));
        seen.insert((game.food_x, game.food_y));
    }

    assert!(seen.len() > 1, "food should land in random places");
}

// ---------- Phase 8: stepping, keys, and the clock ----------

#[test]
fn update_snake_moves_and_resets_timer() {
    let mut game = new_game();
    game.waiting_time = 0.5;

    game.update_snake(None);
    assert_eq!(game.snake.head_position(), (5, 2));
    assert_eq!(game.waiting_time, 0.0);

    game.update_snake(Some(Direction::Down));
    assert_eq!(game.snake.head_position(), (5, 3));
    assert!(!game.game_over);
}

#[test]
fn update_snake_ends_game_on_crash() {
    let mut game = new_game();
    game.snake = Snake::new(26, 2); // head at (28, 2), wall just ahead
    game.waiting_time = 0.5;

    game.update_snake(None);

    assert!(game.game_over);
    assert_eq!(
        game.snake.head_position(),
        (28, 2),
        "a dead snake should not move"
    );
    assert_eq!(game.waiting_time, 0.0);
}

#[test]
fn update_snake_eats_food_in_its_path() {
    let mut game = new_game();
    game.food_x = 5;
    game.food_y = 2;

    game.update_snake(None);

    assert_eq!(game.snake.head_position(), (5, 2));
    assert!(!game.food_exists);
    assert_eq!(game.snake.len(), 4);
}

#[test]
fn key_pressed_arrow_keys_turn_and_move() {
    let mut game = new_game();

    game.key_pressed(Key::Down);
    assert_eq!(game.snake.head_direction(), Direction::Down);
    assert_eq!(game.snake.head_position(), (4, 3));

    game.key_pressed(Key::Left);
    assert_eq!(game.snake.head_direction(), Direction::Left);
    assert_eq!(game.snake.head_position(), (3, 3));
}

#[test]
fn key_pressed_ignores_opposite_direction() {
    let mut game = new_game(); // facing Right

    game.key_pressed(Key::Left);

    assert_eq!(game.snake.head_direction(), Direction::Right);
    assert_eq!(game.snake.head_position(), (4, 2));
    assert!(!game.game_over);
}

#[test]
fn key_pressed_does_nothing_when_game_over() {
    let mut game = new_game();
    game.game_over = true;

    game.key_pressed(Key::Down);

    assert_eq!(game.snake.head_direction(), Direction::Right);
    assert_eq!(game.snake.head_position(), (4, 2));
}

#[test]
fn update_waits_for_moving_period() {
    let mut game = new_game();

    game.update(0.05);
    assert_eq!(game.snake.head_position(), (4, 2), "moved too early");
    assert!((game.waiting_time - 0.05).abs() < 1e-9);

    game.update(0.06);
    assert_eq!(game.snake.head_position(), (5, 2), "should have moved");
    assert_eq!(game.waiting_time, 0.0);
}

#[test]
fn update_adds_food_when_missing() {
    let mut game = new_game();
    game.food_exists = false;

    game.update(0.0);

    assert!(game.food_exists);
    assert!(game.food_x > 0 && game.food_x < 29);
    assert!(game.food_y > 0 && game.food_y < 29);
}

#[test]
fn update_restarts_after_restart_time() {
    let mut game = new_game();
    game.snake.move_forward(Some(Direction::Down)); // head at (4, 3)
    game.food_exists = false;
    game.game_over = true;

    game.update(0.5);
    assert!(game.game_over, "restarted too early");
    assert_eq!(
        game.snake.head_position(),
        (4, 3),
        "snake moved during game over"
    );
    assert!(!game.food_exists, "food added during game over");

    game.update(0.6);
    assert!(!game.game_over, "should have restarted");
    assert_eq!(game.snake.head_position(), (4, 2));
    assert!(game.food_exists);
}
